        for (Map.Entry<String, HealthStatus> entry : results.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }

        System.out.println("\nOverall System Status: " + monitor.getSystemStatus().getDescription());
    }

